def svc_date_pattern():
    return r'(?:\d{4}-\d{2}-\d{2}|(?:January|February|March|April|May|June|July|August|September|October|November|December|Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sep|Sept|Oct|Nov|Dec)\s+\d{1,2}(?:st|nd|rd|th)?(?:,)?\s+\d{4})'

def svc_normalize_date(value):
    value = value.strip()
    if re.fullmatch(r'\d{4}-\d{2}-\d{2}', value):
        return value
    match = re.fullmatch(r'([A-Za-z]+)\s+(\d{1,2})(?:st|nd|rd|th)?(?:,)?\s+(\d{4})', value)
    if match is None:
        return None
    months = {'jan':'01','feb':'02','mar':'03','apr':'04','may':'05','jun':'06','jul':'07','aug':'08','sep':'09','oct':'10','nov':'11','dec':'12'}
    month = months.get(match.group(1).lower()[:3])
    if month is None:
        return None
    return match.group(3) + '-' + month + '-' + match.group(2).zfill(2)

def svc_sentences(text):
    result = []
    for match in re.finditer(r'[^.!?]+[.!?]?', text):
        value = match.group(0).strip()
        if value:
            result.append(value)
    return result

def svc_name_pattern():
    return r'[A-Z][A-Za-z0-9&.\x27’_-]*(?:\s+[A-Z][A-Za-z0-9&.\x27’_-]*){0,7}'

def svc_clean_entity(value):
    value = re.sub(r'\s+', ' ', value).strip(' \t\r\n,;.')
    cut = re.search(r'\s+(?:from|between|starting|beginning|commencing)\b', value, re.I)
    if cut is not None:
        value = value[:cut.start()].strip(' ,;.')
    date = svc_date_pattern()
    cut = re.search(r'\s+on\s+' + date + r'\b', value, re.I)
    if cut is not None:
        value = value[:cut.start()].strip(' ,;.')
    return value

def svc_workers(value):
    result = []
    name = svc_name_pattern()
    amount_pattern = r'\$?\d[\d,]*(?:\.\d+)?\s+to\s+(' + name + r')(?=\s*(?:,|\band\b|$))'
    for match in re.finditer(amount_pattern, value):
        worker = match.group(1).strip()
        if worker not in result:
            result.append(worker)
    if result:
        return result
    tail = re.search(r'\bto\s+(.+)$', value, re.I)
    plain = tail.group(1) if tail is not None else value
    plain = re.sub(r'\$?\d[\d,]*(?:\.\d+)?', ' ', plain)
    plain = re.sub(r'\b(?:and|to)\b', ',', plain, flags=re.I)
    for item in plain.split(','):
        worker = re.sub(r'\s+', ' ', item).strip(' ,;')
        if re.fullmatch(name, worker) and worker not in result:
            result.append(worker)
    return result

def svc_kind(value):
    value = re.sub(r'\s+', ' ', value).strip()
    match = re.match(r'([A-Za-z][A-Za-z -]{0,70}?(?:services?|labor|work))\b', value, re.I)
    if match is not None:
        return re.sub(r'\s+', ' ', match.group(1)).strip().lower()
    match = re.search(r'\b(agricultural labor|domestic service|services?|work)\b', value, re.I)
    if match is not None:
        return match.group(1).lower()
    return None

def svc_time(value):
    date = svc_date_pattern()
    match = re.search(r'\bfrom\s+(' + date + r')\s+(?:to|through|until)\s+(' + date + r')', value, re.I)
    if match is None:
        match = re.search(r'\bbetween\s+(' + date + r')\s+and\s+(' + date + r')', value, re.I)
    if match is not None:
        start = svc_normalize_date(match.group(1))
        end = svc_normalize_date(match.group(2))
        if start is not None and end is not None:
            return ['closed_interval', start, end, None]
        return None
    match = re.search(r'\b(?:starting|beginning|commencing)(?:\s+on)?\s+(' + date + r')', value, re.I)
    if match is not None:
        start = svc_normalize_date(match.group(1))
        if start is not None:
            return ['onset_only', start, None, None]
        return None
    match = re.search(r'\b(?:service|services|work|labor)\b[^.;]*?\bon\s+(' + date + r')', value, re.I)
    if match is not None:
        day = svc_normalize_date(match.group(1))
        if day is not None:
            return ['active_on_date', None, None, day]
        return None
    return ['undated', None, None, None]

def svc_place(value):
    venues = [('private home','private home'),('local college club','local college club'),('local chapter of a college fraternity','local chapter of a college fraternity'),('local chapter of a college sorority','local chapter of a college sorority')]
    for phrase, canonical in venues:
        if re.search(r'\b' + re.escape(phrase) + r'\b', value, re.I):
            return [canonical, None, None, False]
    match = re.search(r'\b(?:performed|done)\s+(?:at|in)\s+(.+?)\s+for\s+', value, re.I)
    if match is not None:
        location = svc_clean_entity(match.group(1))
        if location:
            return [None, location, None, False]
    if re.search(r'\b(?:performed|done)\s+(?:at|in|within|outside)\b', value, re.I):
        return [None, None, None, True]
    return [None, None, None, False]

def svc_records(workers, employer, kind, timing, place, form, quote):
