def svc_parse_clause(clause):
    text = clause.strip(' \t\r\n.;')
    match = re.match(r'^(.+?)\s+(?:(?:has|had)\s+)?paid\s+(?:cash\s+)?wages(?:\s+of)?\s+(.+?)\s+for\s+(.+)$', text, re.I)
    if match is not None:
