    if match is not None:
        workers = svc_workers(match.group(1))
        employer = svc_clean_entity(match.group(3))
        tail = match.group(2) + ' performed for ' + match.group(3)
        return svc_records(workers, employer, svc_kind(match.group(2)), svc_time(tail), svc_place(tail), 'passive_paid_for_service', clause)
    match = re.match(r'^(.+?)\s+(?:performed|did)\s+(.+?)\s+for\s+(.+)$', text, re.I)
    if match is not None:
        workers = svc_workers(match.group(1))
        employer = svc_clean_entity(match.group(3))
        tail = match.group(2) + ' for ' + match.group(3)
        return svc_records(workers, employer, svc_kind(match.group(2)), svc_time(tail), svc_place(text), 'active_service', clause)
    match = re.match(r'^(.+?)\s+(?:worked|works)\s+for\s+(.+)$', text, re.I)
    if match is not None:
        workers = svc_workers(match.group(1))
        employer = svc_clean_entity(match.group(2))
        return svc_records(workers, employer, 'work', svc_time(match.group(2)), svc_place(text), 'active_service', clause)
    match = re.match(r'^(.+?)\s+(?:was|were)\s+(?:performed|done)\s+by\s+(.+?)\s+for\s+(.+)$', text, re.I)
    if match is not None:
        workers = svc_workers(match.group(2))
        employer = svc_clean_entity(match.group(3))
        return svc_records(workers, employer, svc_kind(match.group(1)), svc_time(text), svc_place(text), 'passive_service', clause)
    return None

def svc_has_cue(clause):
    return re.search(r'\b(?:service|services|labor|work|worked|employment|wages)\b', clause, re.I) is not None

